citation_checks:{
literature_identity:pass(`The primary title/authors are Buyang Li and Yifei Wu, An Unfiltered Low-Regularity Integrator for the KdV Equation with Solutions Below H1. The author-hosted access record binds PDF SHA256 ${lsha}; the PDF extraction is the complete 50-page manuscript selected by problem.md. Independent DOI read confirms the same authors/title, Foundations of Computational Mathematics 26, 1321–1380 (2026).`,[`${lw}:1-28`,"problem.md:821-824","source-942156739660edbdf9e8ff36bee3551db77c84ede95934ac57912a8813195ea0.txt:1-24"]),
result_location:pass("The zero-based grid and update range occur at lines 208–212, repeated before (4.4) at 2090–2091. The constant mean-zero bilinear stage is (7.2)–(7.3), lines 3844–3875; Lemma 7.2 and its complete beta0 cases are lines 3877–3907, with proof through line 4130 (manuscript pp.32–34).", [ `${lw}:208-212`,`${lw}:2090-2091`,`${lw}:3844-4130`]),
statement_fidelity:pass("Writing source gamma as sigma, the power (1+sigma-beta)/(1+sigma-beta0), closed beta interval [beta0,1+sigma], three beta0 cases, and fixed positive loss at sigma=1/2 all match Lemma 7.2. Inputs are time-independent, mean-zero H^sigma, 0<sigma<=1. The zero-based step range is explicit in the source grid. Renaming the source horizon to Lsrc*tau makes base zero admissible for every tau>0 without fixing the project horizon. Uniformity in base, step and horizon is supported by the proof's length<=tau low-order bound (7.4), endpoint high-order bound, and interpolation; no exact/numerical solution norm enters those bounds. Unnormalized norms are retained in E003.",["nl0.json#/propositions/5/statement",`${lw}:208-212`,`${lw}:3844-3928`,`${lw}:3983-4130`]),
